import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';

// ── Storage polyfill (replaces Claude's window.storage API) ──────────────────
// Saves all game data to the browser's localStorage so progress
// and streaks persist between sessions on the deployed version.
window.storage = {
  _store: JSON.parse(localStorage.getItem('_ngtrivia') || '{}'),
  _save() {
    try {
      localStorage.setItem('_ngtrivia', JSON.stringify(this._store));
    } catch (e) {
      console.warn('Storage save failed:', e);
    }
  },
  async get(key) {
    const val = this._store[key];
    if (val === undefined) throw new Error(`Key not found: ${key}`);
    return { key, value: val };
  },
  async set(key, value) {
    this._store[key] = value;
    this._save();
    return { key, value };
  },
  async delete(key) {
    delete this._store[key];
    this._save();
    return { key, deleted: true };
  },
  async list(prefix) {
    const keys = Object.keys(this._store).filter(
      k => !prefix || k.startsWith(prefix)
    );
    return { keys };
  },
};

// ── Render ────────────────────────────────────────────────────────────────────
const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);